<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ArrowRight, Collection, Download, Files, FolderOpened, Guide, InfoFilled, MagicStick, Warning } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import CapabilityManifestCard from '../components/CapabilityManifestCard.vue'
import { portalApi } from '../api/portal'
import { profileToRecord, profileVersions, skillProfileById, skillProfileBySlug } from '../skillCatalog'
import { packageFiles, rawSkillDefinition, skillDeepDive } from '../skillExperience'
import type { SkillDetail } from '../types'

const route = useRoute()
const router = useRouter()
const detail = ref<SkillDetail | null>(null)
const loading = ref(true)
const downloading = ref(false)
const activeSection = ref('overview')
const skill = computed(() => detail.value?.skill)
const profile = computed(() => skill.value ? skillProfileBySlug.get(skill.value.slug) : skillProfileById.get(String(route.params.id)))
const files = computed(() => profile.value ? packageFiles(profile.value) : [])
const deepDive = computed(() => profile.value ? skillDeepDive(profile.value) : null)
const rawDefinition = computed(() => profile.value ? rawSkillDefinition(profile.value) : '')
let sectionObserver: IntersectionObserver | null = null

function setupSectionObserver() {
  sectionObserver?.disconnect()
  sectionObserver = new IntersectionObserver((entries) => {
    const visible = entries.filter(entry => entry.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]
    if (visible?.target.id) activeSection.value = visible.target.id
  }, { rootMargin: '-110px 0px -68% 0px', threshold: [0, 0.15, 0.45] })
  document.querySelectorAll<HTMLElement>('[data-skill-section]').forEach(section => sectionObserver?.observe(section))
}

async function load() {
  loading.value = true
  const localProfile = skillProfileById.get(String(route.params.id))
  if (localProfile) {
    detail.value = { skill: profileToRecord(localProfile), versions: profileVersions(localProfile), downloadAvailable: false }
    loading.value = false
    await nextTick()
    setupSectionObserver()
    return
  }
  try { detail.value = await portalApi.skill(String(route.params.id)) }
  catch { ElMessage.error('Skill 详情读取失败') }
  finally {
    loading.value = false
    await nextTick()
    setupSectionObserver()
  }
}

async function download() {
  if (!skill.value) return
  if (profile.value && !detail.value?.downloadAvailable) {
    ElMessage.info('该案例已完成内容导入，能力包尚未进入平台制品库')
    return
  }
  downloading.value = true
  try {
    const response = await portalApi.downloadSkill(skill.value.id)
    const url = URL.createObjectURL(response.data)
    const link = document.createElement('a'); link.href = url; link.download = `${skill.value.slug}.zip`; link.click()
    URL.revokeObjectURL(url); skill.value.downloadCount++
  } catch { ElMessage.warning('该 Skill 暂无可下载的已发布包') }
  finally { downloading.value = false }
}

function scrollToSection(id: string) {
  activeSection.value = id
  document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

function scrollToQuickStart() { scrollToSection('quick-start') }

onMounted(load)
onBeforeUnmount(() => sectionObserver?.disconnect())
</script>

<template>
  <section v-loading="loading" class="detail-page">
    <div v-if="skill" class="container">
      <button class="back" type="button" @click="router.push('/skills')"><el-icon><ArrowLeft /></el-icon>返回 Skill 能力库</button>

      <template v-if="profile">
        <header class="capability-head" :style="{ '--accent': profile.accent }">
          <div class="head-copy">
            <div class="head-kicker"><span>{{ profile.maturity }}</span></div>
            <h1>{{ profile.name }}</h1>
            <p>{{ profile.tagline }}</p>
          </div>
          <div class="head-actions">
            <el-button size="large" @click="scrollToQuickStart">查看上手说明<el-icon class="el-icon--right"><ArrowRight /></el-icon></el-button>
            <el-button type="primary" size="large" :icon="Download" :loading="downloading" @click="download">下载能力包</el-button>
            <small>{{ profile.deployment.guide }}</small>
          </div>
        </header>

        <div v-if="deepDive" class="unified-layout">
          <aside class="skill-sidebar">
            <CapabilityManifestCard :asset="profile">
              <template #action><el-button type="primary" :icon="Download" :loading="downloading" @click="download">下载当前版本</el-button></template>
            </CapabilityManifestCard>

            <nav class="side-card unified-nav" aria-label="Skill 完整目录">
              <b class="nav-title"><el-icon><Guide /></el-icon>内容目录</b>
              <button :class="{ active: activeSection === 'overview' }" @click="scrollToSection('overview')">能力概览</button>
              <button :class="{ active: activeSection === 'readiness' }" @click="scrollToSection('readiness')">使用条件与边界</button>
              <button :class="{ active: ['io','workflow'].includes(activeSection) }" @click="scrollToSection('io')">输入、输出与流程</button>
              <button :class="{ active: ['quality','risk'].includes(activeSection) }" @click="scrollToSection('quality')">质量与风险</button>
              <button :class="{ active: ['quick-start','manual','handoff','faq'].includes(activeSection) }" @click="scrollToSection('quick-start')">使用和维护</button>
              <button :class="{ active: ['package-files','definition','deploy','version-history'].includes(activeSection) }" @click="scrollToSection('package-files')">能力包与版本</button>
            </nav>
          </aside>

          <main class="unified-content">
            <section id="overview" data-skill-section class="content-card overview-card">
              <div class="section-heading"><span>01</span><div><small>POSITIONING & VALUE</small><h2>定位、价值与适用场景</h2></div></div>
              <p class="lead">{{ profile.description }}</p>
              <p class="reading-paragraph"><b>适用场景：</b>{{ profile.scenarios.join('；') }}。</p>
              <p class="reading-paragraph"><b>常见发起方式：</b>安装能力包后，可使用“{{ profile.triggerWords.join('”“') }}”等自然语言发起，并同时说明项目背景、材料范围和期望输出。</p>
            </section>

            <section id="readiness" data-skill-section class="content-card">
              <div class="section-heading"><span>02</span><div><small>READINESS & BOUNDARY</small><h2>启动门槛与不适用边界</h2></div></div>
              <div class="reading-table">
                <article v-for="item in deepDive.readiness" :key="item.title"><h3>{{ item.title }}</h3><p>{{ item.detail }}</p></article>
              </div>
              <div class="not-for"><h3><el-icon><Warning /></el-icon>不应该这样使用</h3><p v-for="item in deepDive.notFor" :key="item">{{ item }}</p></div>
            </section>

            <section id="io" data-skill-section class="content-card">
              <div class="section-heading"><span>03</span><div><small>INPUT & OUTPUT</small><h2>输入材料与可交付结果</h2></div></div>
              <div class="io-flow">
                <div class="io-column input-column"><h3><el-icon><Files /></el-icon>输入要求</h3><article v-for="item in profile.inputs" :key="item.name"><b>{{ item.name }}</b><p>{{ item.detail }}</p><span v-if="item.formats">{{ item.formats }}</span></article></div>
                <div class="flow-arrow"><el-icon><ArrowRight /></el-icon><span>规则执行</span></div>
                <div class="io-column output-column"><h3><el-icon><MagicStick /></el-icon>交付结果</h3><article v-for="item in profile.outputs" :key="item.name"><b>{{ item.name }}</b><p>{{ item.detail }}</p><span v-if="item.formats">{{ item.formats }}</span></article></div>
              </div>
            </section>

            <section id="workflow" data-skill-section class="content-card">
              <div class="section-heading"><span>04</span><div><small>EXECUTION LOGIC</small><h2>能力执行流程与判断逻辑</h2></div></div>
              <ol class="workflow reading-list"><li v-for="step in profile.workflow" :key="step.title"><h3>{{ step.title }}</h3><p>{{ step.detail }}</p></li></ol>
              <p class="process-note">执行过程中必须保留“输入来源—检查规则—问题证据—处理建议”的追溯链，不能只给结论。</p>
            </section>

            <section id="quality" data-skill-section class="content-card">
              <div class="section-heading"><span>05</span><div><small>QUALITY DIMENSIONS</small><h2>质量维度与证据要求</h2></div></div>
              <div class="quality-detail-table">
                <article v-for="(item,index) in deepDive.qualityDetails" :key="item.name"><b>{{ String(index + 1).padStart(2, '0') }}</b><div><h3>{{ item.name }}</h3><p>{{ item.focus }}</p></div><span><small>应保留证据</small>{{ item.evidence }}</span></article>
              </div>
              <div class="boundary-list wide"><h3><el-icon><Warning /></el-icon>必须人工确认</h3><p v-for="item in profile.boundaries" :key="item">{{ item }}</p></div>
            </section>

            <section id="risk" data-skill-section class="content-card">
              <div class="section-heading"><span>06</span><div><small>RISK CLASSIFICATION</small><h2>风险分级与处置动作</h2></div></div>
              <div class="risk-table"><div class="risk-head"><span>等级</span><span>判定含义</span><span>处置要求</span></div><article v-for="item in deepDive.riskLevels" :key="item.level" :class="`risk-${item.level}`"><b>{{ item.level }}</b><p>{{ item.meaning }}</p><span>{{ item.action }}</span></article></div>
            </section>

            <section id="quick-start" data-skill-section class="content-card quick-start-card">
              <div class="section-heading"><span>07</span><div><small>QUICK START</small><h2>四步上手与数据提示</h2></div></div>
              <ol><li v-for="item in profile.quickStart" :key="item"><span>{{ item }}</span></li></ol>
              <div class="security-note"><el-icon><InfoFilled /></el-icon><p><b>数据提示</b>正式项目材料包含业务数据时，建议下载能力包后在公司批准的本地环境运行。</p></div>
            </section>

            <section id="manual" data-skill-section class="manual-document integrated-manual">
              <header><span>USER MANUAL · v{{ profile.version }}</span><h2>{{ profile.name }}使用手册</h2><p>从“怎么发起”到“如何理解输出”的连续操作说明；正式规则以包内 SKILL.md 为准。</p></header>
              <section><em>01</em><div><h3>触发与启动方式</h3><p>安装能力包后，可用自然语言触发，并同时提供项目背景、输入材料、检查范围和期望输出格式。</p><div class="manual-tags"><span v-for="word in profile.triggerWords" :key="word">{{ word }}</span></div></div></section>
              <section><em>02</em><div><h3>输入组织建议</h3><p>先提供项目背景与边界，再按文件目录上传材料。文件名应能体现阶段、版本和责任单位；无法确认的信息要明确标记，不能让 Skill 自行补造事实。</p></div></section>
              <section><em>03</em><div><h3>如何阅读结果</h3><article v-for="item in profile.outputs" :key="item.name" class="manual-output"><b>{{ item.name }}</b><span>{{ item.detail }}</span><small>{{ item.formats }}</small></article></div></section>
            </section>

            <section id="handoff" data-skill-section class="content-card">
              <div class="section-heading"><span>08</span><div><small>BUSINESS HANDOFF</small><h2>与业务流程如何衔接</h2></div></div>
              <div class="handoff-table"><div class="handoff-head"><span>环节</span><span>责任角色</span><span>形成产物</span><span>进入下一环节条件</span></div><article v-for="item in deepDive.handoff" :key="item.stage"><b>{{ item.stage }}</b><span>{{ item.owner }}</span><p>{{ item.deliverable }}</p><em>{{ item.gate }}</em></article></div>
            </section>

            <section id="faq" data-skill-section class="content-card">
              <div class="section-heading"><span>09</span><div><small>FAQ & MAINTENANCE</small><h2>常见问题与维护要求</h2></div></div>
              <div class="faq-list"><details v-for="(item,index) in deepDive.faqs" :key="item.question" :open="index === 0"><summary>{{ item.question }}</summary><p>{{ item.answer }}</p></details></div>
              <div class="maintenance-note"><b>维护责任</b><p>维护人：{{ profile.maintainer }}。规则、模板、案例或业务边界发生变化时，应同步升级版本、更新手册与变更日志，并由内容维护人和质检人员完成双人确认。</p></div>
            </section>

            <section id="package-files" data-skill-section class="package-browser">
              <header><div><span>PACKAGE CONTENTS</span><h2>能力包文件与用途</h2><p>展示当前发布版本的文件结构；系统元数据不参与能力执行。</p></div></header>
              <div class="file-table"><div class="file-table-head"><span>路径</span><span>类型</span><span>大小 / 数量</span><span>用途</span></div><div v-for="file in files" :key="file.path" class="file-row"><code><el-icon><FolderOpened /></el-icon>{{ file.path }}</code><span>{{ file.kind }}</span><span>{{ file.size }}</span><p>{{ file.description }}</p></div></div>
            </section>

            <section id="definition" data-skill-section class="raw-definition">
              <header><div><span>READ ONLY</span><h2>结构化能力定义</h2></div><small>由当前案例结构生成；正式版展示包内原始 SKILL.md</small></header>
              <details class="definition-disclosure"><summary>展开查看完整能力定义</summary><pre><code>{{ rawDefinition }}</code></pre></details>
            </section>

            <section id="deploy" data-skill-section class="download-panel">
              <header><div><span>SERVER PLATFORM</span><h2>能力包下载与本地部署</h2><p>平台只负责提供已发布能力包、版本说明和部署指南，不读取或判断用户本机安装状态。</p></div><el-button type="primary" :icon="Download" :loading="downloading" @click="download">下载 v{{ profile.version }}</el-button></header>
              <div class="deployment-steps"><article><b>01</b><div><h3>下载能力包</h3><p>从平台制品库下载经过审核的 ZIP 包。</p></div></article><article><b>02</b><div><h3>核验与阅读</h3><p>核对版本及完整性，阅读 SKILL.md 和部署说明。</p></div></article><article><b>03</b><div><h3>本地安装</h3><p>由用户在获批的本地环境中自行安装和验证。</p></div></article></div>
            </section>

            <section id="version-history" data-skill-section class="version-timeline standalone"><header><span>VERSION HISTORY</span><h2>版本与升级</h2></header><article v-for="(item,index) in profile.changelog" :key="item.version" :class="{ current: index === 0 }"><i></i><div><b>v{{ item.version }}</b><time>{{ item.date }}</time><p>{{ item.note }}</p></div></article></section>
          </main>
        </div>

      </template>

      <template v-else>
        <header class="generic-head"><div><code>{{ skill.slug }}</code><h1>{{ skill.name }}</h1><p>{{ skill.description || '暂无简介' }}</p></div><el-button type="primary" size="large" :icon="Download" :loading="downloading" @click="download">下载 Skill</el-button></header>
        <div class="generic-layout">
          <main><section><h2><el-icon><Collection /></el-icon>应用案例</h2><p>{{ skill.caseText || '暂无应用案例' }}</p></section><section><h2><el-icon><Guide /></el-icon>使用指南</h2><p>{{ skill.usageGuide || '下载后请先阅读包内 SKILL.md' }}</p></section></main>
          <aside class="side-card"><b>版本记录</b><article v-for="version in detail?.versions" :key="version.id"><strong>{{ version.versionName }}</strong><p>{{ version.changeNote || '未填写变更说明' }}</p></article></aside>
        </div>
      </template>
    </div>
  </section>
</template>

